INSERT OR IGNORE INTO techniques (slug, display_name, category, description) VALUES
('family-emergency-impersonation','Family Emergency Impersonation','social-engineering','A third party claims a relative is in urgent trouble (hospital, jail, accident) and unreachable, then asks for immediate money. Real emergencies allow verification; scams forbid it.'),
('urgency-pressure','Urgency / Time Pressure','social-engineering','Artificial deadlines ("tonight", "within 24 hours") designed to prevent the target from pausing, verifying, or consulting anyone.'),
('isolation-tactic','Isolation Tactic','social-engineering','Instructions to keep the request secret or avoid contacting other family members, banks, or authorities — cutting the target off from anyone who would recognize the scam.'),
('fabricated-pretext','Fabricated Pretext','social-engineering','An invented reason why normal channels cannot be used — "insurance delays," "her phone died," "he can''t call you himself." The excuse exists to block the verification step that would expose the scam.'),
('romance-affinity','Romance / Affinity Scam','social-engineering','A cultivated online relationship is leveraged into financial requests, often with reasons why the person can never meet or video call.'),
('credential-phishing','Credential Phishing','phishing','A fake login page or verification request designed to capture usernames, passwords, or one-time codes.'),
('lookalike-domain','Lookalike Domain','phishing','A domain visually mimicking a trusted brand (paypa1.com vs paypal.com) to make fraudulent messages appear legitimate.'),
('smishing-fake-alert','Fake Security Alert','phishing','A message impersonating a bank or service fraud alert, instructing the target to "verify" or "reverse" a transaction via a link or by sending money.'),
('payment-link-in-email','Payment Link in Email','phishing','An unsolicited email embedding a direct payment link — legitimate organizations route payments through their own platforms, not email links.'),
('pig-butchering','Pig Butchering (Investment Grooming)','crypto','A long-con where trust is built over weeks before steering the target into a fake investment platform showing fabricated gains that can never be withdrawn.'),
('fake-withdrawal-fee','Fake Withdrawal / Gas Fee','crypto','A demand for an upfront "fee", "tax", or "gas payment" to release supposed winnings or investment profits. Each payment triggers a new fee.'),
('pump-and-dump','Pump-and-Dump Promotion','crypto','Coordinated hype ("guaranteed 10x", "insider signal") to inflate a token the promoters already hold and intend to dump.'),
('crypto-doubling','Crypto Doubling / Giveaway','crypto','A promise — often using an impersonated celebrity — that crypto sent to an address will be returned doubled. Blockchain transfers are irreversible; nothing comes back.'),
('task-employment-scam','Task / Employment Scam','employment','A fake job requiring upfront payment for equipment, training, or to "unlock" commissions and salary.'),
('advance-fee','Advance Fee Fraud','employment','An upfront payment demanded to release a larger promised sum (inheritance, loan, prize) that does not exist.'),
('sextortion-panic','Sextortion / Panic Extortion','extortion','A threat to release compromising material (usually nonexistent) unless paid immediately, engineered to cause panic-compliance.'),
('authority-impersonation','Government / Authority Impersonation','impersonation','Impersonation of the IRS, police, courts, or immigration services demanding payment under threat of arrest or legal action. Agencies do not demand payment by gift card, wire, or crypto.'),
('overpayment-refund','Overpayment / Refund Scam','payment-fraud','A claimed accidental overpayment with a request to "refund the difference" — the original payment is fake or will be reversed, leaving the target out the refunded amount.'),
('first-time-recipient','First-Time Recipient','payment-fraud','Payment directed to a recipient the sender has never paid before — a weak signal alone, meaningful in combination with pressure tactics.'),
('large-transfer','Unusually Large Transfer','payment-fraud','A transfer significantly above the account''s normal pattern, requested under pressure.'),
('unusual-payment-method','Unusual Payment Method','payment-fraud','Demands for gift cards, wire transfers, or crypto — irreversible channels favored precisely because they cannot be clawed back.'),
('pretexting-bec','Pretexting / Business Email Compromise','impersonation','Impersonation of an executive, vendor, or attorney directing urgent payment, often with instructions to bypass normal approval ("don''t alert finance").'),
('cross-layer-correlation','Coordinated Multi-Channel Attack','social-engineering','A scam message followed within minutes by a matching payment attempt — the strongest signal of an active, guided fraud in progress.');
